  foreach(var q in colors){var m=Mat(q.Key,q.Value,q.Key=="Steel"?.72f:q.Key=="Green"?.3f:0,q.Key=="Steel"?.42f:.23f);if(new[]{"Coat","Green","Rust","Wood"}.Contains(q.Key))m.SetTexture("_BaseMap",AssetDatabase.LoadAssetAtPath<Texture2D>(E+"Textures/F1_SurfaceWear.png"));if(q.Key=="Floor")m.SetTexture("_BaseMap",AssetDatabase.LoadAssetAtPath<Texture2D>(E+"Textures/F1_Concrete.png"));}
