 static GameObject Place(string name,string asset,Transform parent,Vector3 pos,float yaw=0,bool collision=false,bool structure=false){var src=AssetDatabase.LoadAssetAtPath<GameObject>(asset);if(!src)throw new Exception("Missing model "+asset);var g=(GameObject)PrefabUtility.InstantiatePrefab(src,parent);g.name=name;g.transform.SetPositionAndRotation(pos,Quaternion.Euler(0,yaw,0));foreach(var c in g.GetComponentsInChildren<Collider>(true))UnityEngine.Object.DestroyImmediate(c);var rs=g.GetComponentsInChildren<Renderer>();
