 public static object Run(){if(Application.isPlaying||SceneManager.GetActiveScene().isDirty)throw new Exception("Saved edit required");if(File.Exists(S))throw new Exception("New 1F scene already exists; use scoped edits");Import();if(!AssetDatabase.CopyAsset("Assets/Afrer_Seconds/01.Scenes/Stage/Level_B1_Circular.unity",S))throw new Exception("Scene copy failed");var s=EditorSceneManager.OpenScene(S);var player=s.GetRootGameObjects().Single(g=>g.name.StartsWith("Player"));foreach(var g in s.GetRootGameObjects().Where(g=>g!=player&&g.name!="Camera"))UnityEngine.Object.DestroyImmediate(g);Lightmapping.lightingDataAsset=null;StaticOcclusionCulling.Clear();
  var plan=JObject.Parse(File.ReadAllText(H+"resolved.json"));var root=new GameObject("1F_AbandonedFactory").transform;var sectors=new Dictionary<string,Transform>();foreach(var r in plan["rooms"])sectors[(string)r["id"]]=Child("1F_"+(string)r["id"],root).transform;foreach(var t in plan["tunnels"])sectors[(string)t["id"]]=Child("1F_"+(string)t["id"],root).transform;sectors["OUT"]=Child("1F_Exterior",root).transform;
  foreach(var m in JObject.Parse(File.ReadAllText(H+"models_environment.json"))){string id=m.Key.Split('_')[0];var parent=sectors.ContainsKey(id)?sectors[id]:root;bool collider=!m.Key.EndsWith("Roof")&&m.Key!="FloorMarkings";Place("F1_"+m.Key,(string)m.Value["asset"],parent,Vector3.zero,collision:collider,structure:m.Key.EndsWith("Walls")||m.Key=="GroundFloor");}
