  }
  var lights=Child("Lighting",root).transform;foreach(var r in plan["rooms"]){string id=(string)r["id"];float x=(float)r["x"],z=(float)r["z"],h=(float)r["h"];int count=id=="C01"?6:id=="C02"?4:2;for(int i=0;i<count;i++){float xx=id=="C01"?(i%3-1)*8:(i%2-.5f)*(float)r["w"]*.48f;float zz=count>2?(i/(count/2)-.5f)*(float)r["d"]*.48f:0;Light(lights,id+"_TaskLight_"+i,new Vector3(x+xx,h-.8f,z+zz),h*1.65f,id=="C01"?4.4f:3.0f,id=="C04"||id=="C03",i==0&&id.StartsWith("C"));}}
