  string skypath=E+"Materials/F1_OvercastSky.mat";var sky=AssetDatabase.LoadAssetAtPath<Material>(skypath);if(!sky){sky=new Material(Shader.Find("Skybox/Procedural")){name="F1_OvercastSky"};sky.SetColor("_SkyTint",new Color(.61f,.67f,.7f));sky.SetColor("_GroundColor",new Color(.39f,.41f,.38f));sky.SetFloat("_Exposure",1.05f);AssetDatabase.CreateAsset(sky,skypath);}RenderSettings.skybox=sky;RenderSettings.ambientMode=AmbientMode.Trilight;RenderSettings.ambientSkyColor=new Color(.53f,.57f,.59f);RenderSettings.ambientEquatorColor=new Color(.38f,.41f,.4f);RenderSettings.ambientGroundColor=new Color(.23f,.25f,.23f);RenderSettings.reflectionIntensity=.65f;RenderSettings.fog=false;
